propuesta.texto_nuevo:
tocados = [b for b in bloques if viejo in "\n".join(b)]
if not tocados:
    # El trozo no vino en el paquete (codigo nuevo o el bibliotecario no lo trajo).
    # Se busca en el DISCO para que el revisor lo vea y no rechace por 'no aparece
    # en el material'. Nunca lanza: si no se encuentra, se devuelve base como hoy.
    try:
        ruta = str(propuesta.get('archivo') or '')
        if ruta and os.path.isfile(ruta):
            with open(ruta, 'r', encoding='utf-8', errors='replace') as _f:
                contenido = _f.read()
            if viejo in contenido:
                _linea_viejo = contenido[:contenido.index(viejo)].count(chr(10)) + 1
                _trozo = None
                try:
                    _arbol = ast.parse(contenido)
                    for _nodo in _arbol.body:
                        if isinstance(_nodo, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                            _ini = getattr(_nodo, 'lineno', None)
                            _fin = getattr(_nodo, 'end_lineno', None)
                            if _ini is not None and _fin is not None and _ini <= _linea_viejo <= _fin:
                                _trozo = contenido.splitlines()[_ini - 1:_fin]
                                break
                except Exception:
                    _trozo = None
                if _trozo is None:
                    _lineas_disco = contenido.splitlines()
                    _ini = max(0, _linea_viejo - 15)
                    _fin = min(len(_lineas_disco), _linea_viejo + 15)
                    _trozo = _lineas_disco[_ini:_fin]
                if _trozo:
                    arriba = ["## EL CAMBIO SE HACE AQUI (trozo entero)"]
                    arriba += _trozo
                    resultado = "\n".join(arriba) + "\n" + base
                    if len(resultado) > tope:
                        resultado = resultado[:tope]
                    return resultado
    except Exception:
        pass
    return base
